const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const requesterId = parseInt(match[1], 10);
const body = $input.first().json.body || {};
const contactId = parseInt(body.id, 10);

if (!Number.isInteger(contactId)) throw new Error('"id" must be an integer.');

// Only fields actually present in the request body get updated (true
// partial-update semantics) — an omitted key leaves that column untouched,
// while a key explicitly sent (even as '') sets/clears it. This lets
// callers like the "do not contact" toggle send just {id, do_not_contact}
// without wiping every other field, while the full edit form can still
// clear a field by submitting an empty string.
function field(...names) {
  for (const name of names) {
    if (body[name] !== undefined) return (body[name] ?? '').toString().trim();
  }
  return undefined;
}

const accountId = body.account_id === undefined
  ? undefined
  : (body.account_id === null || body.account_id === '')
    ? null
    : parseInt(body.account_id, 10);

if (accountId !== undefined && accountId !== null && !Number.isInteger(accountId)) {
  throw new Error('"account_id" must be an integer or null.');
}

return [{
  json: {
    requesterId,
    contactId,
    first_name: field('first_name'),
    last_name: field('last_name'),
    job_title: field('job_title'),
    account_id: accountId,
    email: field('email'),
    secondary_email: field('secondary_email'),
    phone: field('phone'),
    secondary_phone: field('secondary_phone'),
    linkedin_url: field('linkedin_url'),
    lead_status: field('lead_status', 'status'),
    lead_source: field('lead_source'),
    city: field('city'),
    state: field('state'),
    zip_code: field('zip_code'),
    country: field('country'),
    do_not_contact: body.do_not_contact === undefined ? undefined : (body.do_not_contact === true || body.do_not_contact === 'true'),
    dnc_email: body.dnc_email === undefined ? undefined : (body.dnc_email === true || body.dnc_email === 'true'),
    dnc_call: body.dnc_call === undefined ? undefined : (body.dnc_call === true || body.dnc_call === 'true'),
    dnc_sms: body.dnc_sms === undefined ? undefined : (body.dnc_sms === true || body.dnc_sms === 'true')
  }
}];

const requester = $('Look Up Requester').first().json;
const c = $('Parse Token & Payload').first().json;
const oldContact = $input.first().json.old_contact;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!oldContact) throw new Error('Contact not found or you do not have permission to edit it.');

// Only build a SET clause for fields the caller actually included in the
// request body (see "Parse Token & Payload") — omitted fields stay
// untouched, and a field explicitly sent as '' now genuinely clears it
// instead of silently falling back to the old value.
const fieldColumns = [
  'first_name', 'last_name', 'job_title', 'account_id',
  'email', 'secondary_email', 'phone', 'secondary_phone', 'linkedin_url',
  'lead_status', 'lead_source', 'city', 'state', 'zip_code', 'country',
  'do_not_contact', 'dnc_email', 'dnc_call', 'dnc_sms',
];

const setClauses = [];
const queryParams = [];
let idx = 1;

for (const col of fieldColumns) {
  if (c[col] === undefined) continue;
  setClauses.push(`${col} = $${idx}`);
  queryParams.push(c[col]);
  idx++;
}

setClauses.push('updated_at = NOW()');

const sqlQuery = `
  UPDATE contacts SET
    ${setClauses.join(',\n    ')}
  WHERE id = $${idx} AND ($${idx + 1} = 'admin' OR owner_id = $${idx + 2})
  RETURNING *;
`;

queryParams.push(c.contactId, requester.role, requester.id);

return [{ json: { sqlQuery, queryParams, oldContact } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Contact not found or you do not have permission to edit it.');
}
return [{ json: { success: true, contact: result.json } }];

const requesterName = $('Look Up Requester').first().json.name || 'Someone';
const requesterId = $('Look Up Requester').first().json.id;
const oldContact = $('Build Update Query').first().json.oldContact || {};
const newContact = $input.first().json.contact;
const contactId = $('Parse Token & Payload').first().json.contactId;

// Only fields with a human-readable value are audited — account_id is
// excluded because the raw contacts row only has the numeric id, not the
// joined company name, and showing "Company changed from 4 to 9" would
// confuse reps more than it'd help (see ContactDetailModal read-only field
// feedback: avoid anything that reads like a raw id/input to a rep).
const FIELD_LABELS = {
  first_name: 'First Name', last_name: 'Last Name', job_title: 'Job Title',
  email: 'Email', secondary_email: 'Secondary Email', phone: 'Phone Number',
  secondary_phone: 'Secondary Phone', linkedin_url: 'LinkedIn Profile',
  lead_status: 'Status', lead_source: 'Lead Source', city: 'City', state: 'State',
  zip_code: 'Zip Code', country: 'Country', do_not_contact: 'Do Not Contact',
  dnc_email: 'DNC: Email', dnc_call: 'DNC: Call', dnc_sms: 'DNC: SMS',
};

function fmt(v) {
  if (v === null || v === undefined || v === '') return 'empty';
  if (typeof v === 'boolean') return v ? 'Yes' : 'No';
  return String(v);
}

const rows = [];
for (const [field, label] of Object.entries(FIELD_LABELS)) {
  if (!(field in oldContact)) continue;
  const oldVal = oldContact[field];
  const newVal = newContact[field];
  const oldNorm = oldVal === null ? '' : oldVal;
  const newNorm = newVal === null ? '' : newVal;
  if (String(oldNorm) === String(newNorm)) continue;
  rows.push({
    summary: `${requesterName} updated ${label} from ${fmt(oldVal)} to ${fmt(newVal)}`,
    detail: JSON.stringify({ field, old: oldVal, new: newVal }),
  });
}

if (rows.length === 0) {
  // A no-op query that always returns exactly one row — a Postgres node
  // downstream of this one that yields zero output items would silently
  // stop the whole execution chain (n8n doesn't run a node with zero input
  // items), so "SELECT 1;" is used instead of a WHERE-false query.
  return [{ json: { sqlQuery: 'SELECT 1;', queryParams: [] } }];
}

const valuesSql = [];
const queryParams = [];
let idx = 1;
for (const row of rows) {
  valuesSql.push(`($${idx}, $${idx + 1}, $${idx + 2}, $${idx + 3}, $${idx + 4}, $${idx + 5}::jsonb, $${idx + 6}, $${idx + 7})`);
  queryParams.push('contact', contactId, 'system_audit', 'field_change', row.summary, row.detail, requesterId, requesterName);
  idx += 8;
}

const sqlQuery = `INSERT INTO entity_activity_log (entity_type, entity_id, category, subtype, summary, detail, actor_id, actor_name) VALUES ${valuesSql.join(', ')} RETURNING id;`;

return [{ json: { sqlQuery, queryParams } }];
